n=int(input())
ppairs=[]
npairs=[]
for i in range(n):
	ti,xi=list(map(int,input().split()))
	if (xi-ti)>=0:
		ppairs.append([ti,xi])
	else:
		npairs.append([ti,xi])

ppairs.sort(reverse=True,key=lambda x: (x[1]+0.0)/x[0])
